import {ingredients} from './cafe-content.mjs';
import {availableIngredients} from './cafe-core.mjs';
import {currentForage,startForage,resumeForage,chooseForage,submitHarvest,supportHarvest,stepHarvest,packHarvest} from './forage-core.mjs';
import {foodArt,qualityIcons,hearButton} from './play-media.mjs';
import {guideRail} from './garden-ui.mjs';
import {numericAnswer} from './core.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const foodOf=id=>ingredients.find(f=>f.id===id);
const button=(action,label,cls='secondary',extra='')=>`<button type="button" class="${cls}" data-forage-action="${action}" ${extra}>${label}</button>`;
export function gatheringShelf(state){
 const c=state.cafe,trip=currentForage(state),foods=availableIngredients(c);
 return `<section class="gathering-shelf"><h2>Gather for the cupboard</h2><p>Follow a food’s trail, find its patch, and bring back a harvest. Each trip fills one jar.</p>${trip?`<div class="resume-strip"><span>${esc(foodOf(trip.ingredientId).name)}: ${trip.collected?'harvest packed':'a trip is waiting'}.</span><a class="secondary" href="#orchard/gather">${trip.collected?'See this trip':'Continue gathering'}</a></div>`:''}<div class="gather-foods">${foods.map(f=>`<a class="gather-food" href="#orchard/gather/${f.id}">${foodArt(f.id)}<strong>${esc(f.name)}</strong><span>${c.stock[f.id]} in the jar</span>${qualityIcons(f.properties)}</a>`).join('')}</div><p class="tiny">Only pretend ingredients. Jars hold up to 180 bites. A new trip starts only while a jar has 144 or fewer; a full jar never needs gathering.</p></section>`;
}
export function foragePairsShown(state,id){const t=currentForage(state);return t?.stage==='harvest'&&(!id||id===t.ingredientId)?[[t.baskets,t.bites]]:[];}
function baskets(t){return `<div class="harvest-baskets" role="img" aria-label="${t.baskets} baskets with ${t.bites} bites in each; ${t.steps} baskets counted">${Array.from({length:t.baskets},(_,i)=>`<figure class="harvest-basket ${i<t.steps?'counted':''}"><div>${Array.from({length:t.bites},()=>foodArt(t.ingredientId)).join('')}</div><figcaption>Basket ${i+1} · ${t.bites} bites</figcaption></figure>`).join('')}</div>`;}
export function foragePage(state,id){
 const c=state.cafe,t=currentForage(state),wanted=availableIngredients(c).find(f=>f.id===id),matching=t&&(!id||t.ingredientId===id),food=matching?foodOf(t.ingredientId):wanted;
 const opening='<header class="cafe-heading"><a class="back" href="#cafe">← Back to the waiting café</a><h1>A trail to the cupboard</h1><p>Find a patch. Count a harvest. Bring it home.</p></header>';
 let body;
 if(!food)body=gatheringShelf(state);
 else if(!matching)body=`<section class="forage-sheet"><a class="back" href="#orchard">← All orchard trails</a><h2 id="forage-title" tabindex="-1">Follow the ${esc(food.name.toLowerCase())} trail</h2><div class="forage-target">${foodArt(food.id,food.name)}<p>${c.stock[food.id]} bites in the cupboard</p></div><p>Look for this food among the branches. Your guest and recipe will wait.</p>${c.stock[food.id]>144?'<p class="cafe-feedback">This jar has plenty for now. Choose another trail, or return to the café.</p>':`<button class="primary" data-forage-start="${food.id}">Begin this gathering trip</button>`}${t?`<p class="tiny">A previous trip stays in the notebook when you begin another.</p><a class="secondary" href="#orchard/gather">Continue the waiting trip</a>`:''}</section>`;
 else if(t.collected||t.stage==='packed')body=`<section class="forage-sheet"><h2 id="forage-title" tabindex="-1">Harvest packed</h2><div class="forage-target">${foodArt(food.id,food.name)}</div><p class="forage-prompt">You brought back ${t.total} bites of ${esc(food.name.toLowerCase())}.</p><p>${c.stock[food.id]} bites are in this jar now. This trip cannot fill it again.</p><div class="forage-actions"><a class="primary" href="#cafe">Return to our guest</a><a class="secondary" href="#orchard">Explore another trail</a>${c.stock[food.id]<=144?`<button class="text-button" data-forage-start="${food.id}">Begin a new trip for this food</button>`:''}</div><p class="tiny">Gathering is guided play. Packing a harvest does not establish independent fact recall.</p></section>`;
 else if(t.stage==='search'){
 const last=t.searchChoices.at(-1),prompt=`Look for ${food.name.toLowerCase()}. Which patch has this food?`;
 body=`<section class="forage-sheet"><a class="back" href="#orchard">← All orchard trails</a><h2 id="forage-title" tabindex="-1">Find the ${esc(food.name.toLowerCase())} patch</h2><div class="forage-target">${foodArt(food.id,food.name)}<p>We are looking for this food.</p></div>${hearButton(prompt)}<div class="forage-search" role="group" aria-label="Choose a food patch">${t.choices.map((choice,i)=>`<button class="forage-patch forage-patch-${i}" data-forage-choice="${choice}">${foodArt(choice)}<strong>${esc(foodOf(choice).name)}</strong><span>Look in this patch</span></button>`).join('')}</div>${last?`<p class="cafe-feedback" role="status">You found ${esc(foodOf(last).name.toLowerCase())}. Keep looking for ${esc(food.name.toLowerCase())}.</p>`:''}<p>Your basket stays empty until you find this food’s patch.</p></section>`;
 }else{
 const answer=t.attempts.at(-1)===t.total,prompt=`There are ${t.baskets} baskets with ${t.bites} bites in each. How many bites can we bring back?`;
 body=`<section class="forage-sheet"><a class="back" href="#orchard">← All orchard trails</a><h2 id="forage-title" tabindex="-1">A harvest of ${esc(food.name.toLowerCase())}</h2><p class="forage-prompt">${t.baskets} baskets. ${t.bites} bites in each.</p>${hearButton(prompt)}${baskets(t)}${!answer?`<form data-forage-form novalidate><label for="harvest-answer">How many bites can we bring back?</label><div class="cafe-answer-line"><input id="harvest-answer" type="text" inputmode="numeric" maxlength="3" autocomplete="off" value="${esc(t.input)}" aria-describedby="harvest-error"><button class="primary" type="submit">Check our harvest</button></div></form>${t.attempts.length?'<p class="cafe-feedback">Let’s count these baskets together, or try another number.</p>':''}`:'<p class="cafe-feedback" role="status">That number fits the baskets.</p>'}<p id="harvest-error" role="alert">${esc(t.error||'')}</p><div class="forage-actions">${button('count','Count the next basket','secondary',t.steps===t.baskets?'disabled':'')}${!t.revealed?button('reveal','Show the basket total','text-button'):''}</div>${t.supported?`<p class="harvest-readout" aria-live="polite">${t.steps} baskets counted: ${t.steps*t.bites} bites.</p>`:''}${t.revealed?`<p class="cafe-help">${t.baskets} × ${t.bites} = ${t.total} bites. These are equal baskets of the same food.</p>`:''}<div class="forage-actions">${answer?button('pack',`Pack ${t.total} bites for the cupboard`,'primary'):button('pack-help','Pack the harvest with help','primary')}<a class="text-button" href="#cafe">Leave this harvest waiting</a></div><p class="tiny">Only this jar will receive this harvest. Nothing is added until you pack it.</p></section>`;
 }
 return `<div data-forage-view class="orchard-view">${opening}<div class="orchard-layout"><div>${body}</div>${guideRail(state,'{guide} says, “We can follow a trail together. Our guest is happy to wait while we gather.”')}</div></div>`;
}
export function forageNotes(state){
 const f=state.cafe?.foraging,trips=f?.trips||[];
 return `<section class="panel forage-notes"><h2>Gathering trips</h2><p>These are guided pretend searches and harvests, separate from multiplication recall. Up to 24 trips are retained, including a waiting current trip. Only packing a found harvest adds stock.</p>${[...trips].reverse().map(t=>`<details><summary>${esc(foodOf(t.ingredientId).name)} · ${t.collected?'packed':'waiting at '+t.stage}</summary><p>${t.baskets} baskets × ${t.bites} bites = ${t.total}. ${t.collected?'Added once to its jar.':'No stock added.'}</p><p>Search choices: ${t.searchChoices.length}. Harvest answers: ${t.attempts.map(esc).join(', ')||'none'}. Help: ${t.supported?'used':'not recorded'}; total ${t.revealed?'shown':'not shown'}.</p><button class="secondary" data-forage-resume="${t.id}">Return to this trip</button></details>`).join('')||'<p>No gathering trips yet.</p>'}</section>`;
}
export function bindForage(state,{save,render,focus,exposeFacts}){
 const redraw=()=>{save();render();focus('#forage-title');};
 const expose=()=>{const pairs=foragePairsShown(state);if(pairs.length)exposeFacts(pairs);};
 const go=()=>{expose();save();if(location.hash==='#orchard/gather')redraw();else location.hash='#orchard/gather';};
 document.querySelectorAll('[data-forage-start]').forEach(b=>b.addEventListener('click',()=>{if(startForage(state,b.dataset.forageStart))go();}));
 document.querySelectorAll('[data-forage-resume]').forEach(b=>b.addEventListener('click',()=>{if(resumeForage(state,b.dataset.forageResume))go();}));
 document.querySelectorAll('[data-forage-choice]').forEach(b=>b.addEventListener('click',()=>{chooseForage(state,b.dataset.forageChoice);expose();redraw();}));
 const input=document.querySelector('#harvest-answer');input?.addEventListener('input',()=>{const t=currentForage(state);if(t?.stage==='harvest'){t.input=input.value.slice(0,3);t.error='';save();}});
 document.querySelector('[data-forage-form]')?.addEventListener('submit',e=>{e.preventDefault();const n=numericAnswer(input.value),t=currentForage(state);if(!Number.isSafeInteger(n)||n<0||n>999){t.error='Use a whole number, or pack with help.';save();document.querySelector('#harvest-error').textContent=t.error;input.focus();return;}submitHarvest(state,n);if(n!==t.total)supportHarvest(state);expose();redraw();});
 document.querySelectorAll('[data-forage-action]').forEach(b=>b.addEventListener('click',()=>{const a=b.dataset.forageAction;if(a==='count')stepHarvest(state);if(a==='reveal')supportHarvest(state,{reveal:true});if(a==='pack-help'){supportHarvest(state,{reveal:true});packHarvest(state);}if(a==='pack')packHarvest(state);expose();redraw();}));
}
